/**
 * Compares the Node port against output produced by the original Python library.
 * References are generated by `tools/gen_golden.py` into `test/golden/`.
 *
 * Models are downloaded on first run (shared cache with the Python libraries).
 */
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { beforeAll, describe, expect, it } from "vitest";
import { ALPR } from "../src/index.js";
import type { ALPRResult } from "../src/index.js";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const goldenDir = join(root, "test", "golden");

const cases = existsSync(goldenDir)
  ? readdirSync(goldenDir)
      .filter((f) => f.endsWith(".json"))
      .map((f) => f.replace(/\.json$/, ""))
      .filter((name) => existsSync(join(root, "assets", `${name}.png`)))
  : [];

// Tolerances. Box coordinates are integers; allow 1px of drift from resize differences
// between OpenCV builds (WASM 4.x here vs. opencv-python in the reference).
const BOX_TOL_PX = 1;
const DET_CONF_TOL = 1e-2;
// OCR confidence tolerance scales with the reference's uncertainty. The OpenCV bilinear resize of
// the Node (WASM 4.10) and Python (5.x) builds differs by at most 1 gray level on ~20% of the
// pixels. On tiny plate crops the model amplifies that. For a softmax output a small logit
// perturbation moves a probability p by roughly p * (1 - p) * delta, so the expected error is
// proportional to (1 - p): confident characters stay very tight, ambiguous ones may move more.
const ocrConfTol = (reference: number): number => Math.max(1e-3, 0.3 * (1 - reference));

let alpr: ALPR;
beforeAll(async () => {
  alpr = await ALPR.create();
});

describe.skipIf(cases.length === 0)("matches the Python fast-alpr", () => {
  for (const name of cases) {
    it(name, async () => {
      const expected = JSON.parse(readFileSync(join(goldenDir, `${name}.json`), "utf-8")) as ALPRResult[];
      const actual = await alpr.predict(join(root, "assets", `${name}.png`));

      expect(actual).toHaveLength(expected.length);

      expected.forEach((exp, i) => {
        const act = actual[i]!;
        expect(act.detection.label).toBe(exp.detection.label);
        expect(Math.abs(act.detection.confidence - exp.detection.confidence)).toBeLessThan(DET_CONF_TOL);
        for (const k of ["x1", "y1", "x2", "y2"] as const) {
          expect(Math.abs(act.detection.boundingBox[k] - exp.detection.boundingBox[k])).toBeLessThanOrEqual(
            BOX_TOL_PX,
          );
        }

        if (exp.ocr === null) {
          expect(act.ocr).toBeNull();
          return;
        }
        expect(act.ocr).not.toBeNull();
        expect(act.ocr!.text).toBe(exp.ocr.text);
        expect(act.ocr!.region).toBe(exp.ocr.region);

        const expConf = exp.ocr.confidence as number[];
        const actConf = act.ocr!.confidence as number[];
        expect(actConf).toHaveLength(expConf.length);
        expConf.forEach((c, k) => expect(Math.abs(actConf[k]! - c)).toBeLessThan(ocrConfTol(c)));
        const expRegionConf = exp.ocr.regionConfidence ?? 0;
        expect(Math.abs((act.ocr!.regionConfidence ?? 0) - expRegionConf)).toBeLessThan(ocrConfTol(expRegionConf));
      });
    });
  }
});

describe("image without plates", () => {
  it("returns an empty list", async () => {
    const blank = { data: new Uint8Array(320 * 240 * 3).fill(128), width: 320, height: 240, channels: 3 as const };
    expect(await alpr.predict(blank)).toEqual([]);
  });
});
